$string['settings:rag_window_size_desc'] = '"window" रिटर्न स्कोप के लिए: मिलान किए गए खंड के प्रत्येक ओर शामिल किए जाने वाले आस-पास के खंडों की संख्या। डिफ़ॉल्ट 1।';
$string['settings:rag_parent_max_chars'] = 'पैरेंट पैसेज सीमा (वर्ण)';
$string['settings:rag_parent_max_chars_desc'] = 'विस्तारित window/page पैसेज के लिए अधिकतम वर्ण संख्या। सीमा से अधिक पेज पहले विंडो में और फिर एकल खंड में वापस चले जाते हैं। डिफ़ॉल्ट 6000।';
