$string['settings:embed_query_model_desc'] = 'जब तक आप निश्चित न हों कि इसकी आवश्यकता है, इसे खाली छोड़ दें। सामान्यतः प्रश्न और पाठ्यक्रम सामग्री एक ही मॉडल से एम्बेड की जाती हैं, जो हर स्थिति में सुरक्षित एकमात्र विकल्प है: भिन्न मॉडलों के वेक्टर तुलनीय नहीं होते, और उन्हें मिलाने पर त्रुटि के बजाय विश्वसनीय दिखने वाले परंतु अर्थहीन परिणाम मिलते हैं। इसे केवल तब सेट करें जब दोनों मॉडल एक ही एम्बेडिंग स्पेस साझा करते हों — वर्तमान में Voyage 4 शृंखला (voyage-4-large, voyage-4, voyage-4-lite, voyage-4-nano), जिनकी परस्पर विनिमेयता प्रलेखित है। लाभ यह है कि आप पूरे पाठ्यक्रम संग्रह को दोबारा एम्बेड किए बिना बाद में प्रश्न मॉडल बदल सकते हैं। यदि मॉडल तुलनीय न निकलें, तो पुनर्प्राप्ति एक चेतावनी दर्ज करती है और उस पाठ्यक्रम के लिए ग़लत अंश लौटाने के बजाय कुछ भी नहीं लौटाती।';
