$string['quizlock:scope_desc'] = 'चल रहा प्रयास [[tutorshort]] को केवल क्विज़ वाले कोर्स में रोके या हर जगह। <strong>केवल यही कोर्स</strong> डिफ़ॉल्ट है और लगभग हमेशा यही उपयुक्त होता है। पूरी साइट पर रोकना v7.2.4 तक का व्यवहार था और उसमें एक ऐसी खामी थी जिसे जानना ज़रूरी है: छोड़ा हुआ प्रयास हमेशा के लिए ‘चल रहा’ बना रहता है, इसलिए शिक्षार्थी के इतिहास में कहीं भूला हुआ एक क्विज़ उसके हर कोर्स में सहायक को बंद कर देता था, और स्क्रीन पर कारण तक नहीं दिखता था। नकल पर आमादा शिक्षार्थी के सामने पूरी साइट पर रोकने से बहुत कम मिलता है — उसके पास दूसरा ब्राउज़र है — और सहायक की कोर्स सामग्री तथा पुनर्प्राप्ति वैसे भी कोर्स तक सीमित हैं।';

$string['settings:prompt_budget_tuner_conflict'] = 'अप्रचलित प्रॉम्प्ट-बजट स्वतः-समायोजन कार्य चालू है, जबकि बजट मोड मॉडल से निकालने पर सेट है। दोनों में टकराव है: कार्य वर्ण-बजट लिखता है, और डिफ़ॉल्ट से भिन्न कोई भी मान जानबूझकर किया गया चयन माना जाता है, जो निकाले गए बजट को बंद कर देता है। इस मोड में कार्य अब स्वयं रुक जाता है, इसलिए कुछ भी अधिलेखित नहीं हो रहा — फिर भी अस्पष्टता हटाने के लिए इसे बंद कर दें।';

$string['settings:prompt_budget_no_window'] = 'ऊपर का बजट मोड मॉडल से निकालने पर सेट है, पर निकालने के लिए कुछ है ही नहीं: चैट मॉडल सेट नहीं है और कोई बैकएंड संदर्भ विंडो भी कॉन्फ़िगर नहीं है, इसलिए निर्धारण नीचे दिए निश्चित वर्ण-बजट पर लौट आता है। चैट मॉडल सेट करें, या बैकएंड संदर्भ विंडो हाथ से सेट करें, फिर बैकएंड स्व-परीक्षण दोबारा चलाकर पुष्टि करें कि संदर्भ-विंडो जाँच पास होती है। तब तक बजट वही है जो नीचे लिखा है, मोड चाहे कुछ भी कहे।';

